fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    // If the input is empty, return an empty vector.
    if n == 0 {
        return Vec::new();
    }

    // Pre‐allocate exactly 2*n - 1 slots:
    // n original elements + (n-1) delimiters
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push each element, and before each element except the first,
    // push the delimiter.
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim);
        }
        res.push(num);
    }

    res
}

